import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlTitleComponent } from '@domg-wc/components/atom';
import { VlSearchFilterComponent } from '@domg-wc/components/block';
import { VlFormLabelComponent, VlInputFieldComponent, VlSelectComponent } from '@domg-wc/components/form';

registerWebComponents([
    VlSearchFilterComponent,
    VlTitleComponent,
    VlFormLabelComponent,
    VlInputFieldComponent,
    VlSelectComponent,
    VlButtonComponent,
]);

// De keuzes van een vl-select zet je met de property options.
document.querySelector('vl-select[name="vl-select-city"]').options = [
    { label: 'Kies een stad', value: '' },
    { label: 'Brussel', value: 'brussel' },
    { label: 'Gent', value: 'gent' },
];
document.querySelector('vl-select[name="vl-select-country"]').options = [
    { label: 'Kies een land', value: '' },
    { label: 'België', value: 'België' },
    { label: 'Frankrijk', value: 'Frankrijk' },
    { label: 'Nederland', value: 'Nederland' },
];

